INSERT INTO `areaclic` VALUES ('mdQuadril','Circunferncia do Quadril','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia do quadril\\plain\\f3\\fs22 \r\n\\par \r\n\\par Quanto a circunfer\\\'eancia do quadril, a fita m\\\'e9trica dever\\\'e1 ser posicionada horizontalmente ao n\\\'edvel dos gl\\\'fateos, na sua m\\\'e1xima circunfer\\\'eancia. O avaliador dever\\\'e1 postar-se \\\'e0 frente do avaliado.\r\n\\par \r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',3);